
(function(){
  const frame=document.getElementById('simNetworkFrame');
  const cards=document.querySelectorAll('[data-gamepanel="simnetwork"]');
  const reward=document.getElementById('simNetworkReward');
  if(!frame)return;
  const source64='';
  let initialized=false;
  function playerName(){
    try{return localStorage.getItem('nq_demo_user')||'Siswa'}catch(e){return 'Siswa'}
  }
  function sendIdentity(){
    try{frame.contentWindow.postMessage({type:'netquest-sim-init',name:playerName()},'*')}catch(e){}
  }
  function loadSimulation(){
    if(initialized)return;
    initialized=true;
    frame.addEventListener('load',function(){sendIdentity();setTimeout(sendIdentity,250)},{once:true});
    try{
      const bytes=Uint8Array.from(atob(source64),ch=>ch.charCodeAt(0));
      frame.srcdoc=new TextDecoder('utf-8').decode(bytes);
    }catch(err){
      frame.srcdoc='<!doctype html><html lang="id"><meta charset="utf-8"><body style="font:16px system-ui;background:#0c1420;color:#fff;padding:24px">Simulasi Jaringan gagal dimuat. Muat ulang halaman NEXORA.</body></html>';
    }
  }
  cards.forEach(card=>card.addEventListener('click',loadSimulation));
  window.addEventListener('message',function(event){
    if(event.source!==frame.contentWindow||!event.data||typeof event.data!=='object')return;
    if(event.data.type==='netquest-sim-project-save'){
      try{
        const project=event.data.project;
        if(!project||project.version!==2||!Array.isArray(project.nodes)||!Array.isArray(project.links)||JSON.stringify(project).length>500000)throw new Error('invalid project');
        const user=(localStorage.getItem('nq_demo_user')||'guest').toLowerCase().slice(0,64);
        localStorage.setItem('netquest_network_lab_v2:'+user,JSON.stringify(project));
        frame.contentWindow.postMessage({type:'netquest-sim-project-saved'},'*');
      }catch(err){frame.contentWindow.postMessage({type:'netquest-sim-project-save-failed'},'*');}
      return;
    }
    if(event.data.type==='netquest-sim-project-load'){
      try{
        const user=(localStorage.getItem('nq_demo_user')||'guest').toLowerCase().slice(0,64);
        const project=JSON.parse(localStorage.getItem('netquest_network_lab_v2:'+user)||'null');
        if(project)frame.contentWindow.postMessage({type:'netquest-sim-project-data',project},'*');
        else frame.contentWindow.postMessage({type:'netquest-sim-project-empty'},'*');
      }catch(err){frame.contentWindow.postMessage({type:'netquest-sim-project-load-failed'},'*');}
      return;
    }
    if(event.data.type==='netquest-sim-progress'){
      const completed=Math.max(0,Number(event.data.completed)||0),total=Math.max(1,Number(event.data.total)||15),skipped=Math.max(0,Number(event.data.skipped)||0);
      if(reward)reward.textContent=completed>=total?(skipped===0?'✓ Semua 15 misi selesai. Bonus +60 XP sedang diproses atau sudah diterima.':`Semua misi telah dilewati/diselesaikan, tetapi ${skipped} misi dilewati. Bonus XP diberikan hanya jika semua misi diselesaikan tanpa melewati.`):`Progres simulasi: ${completed} dari ${total} misi selesai. ${skipped?`Misi dilewati: ${skipped}.`:''}`;
    }
    if(event.data.type==='netquest-sim-completed'){
      if(typeof window.netquestAwardSimNetwork==='function'&&window.netquestAwardSimNetwork()){
        if(reward)reward.textContent='✓ Hebat! Semua 15 misi diselesaikan tanpa dilewati. Kamu memperoleh +60 XP NEXORA! Bonus ini hanya diberikan satu kali per akun.';
      }else if(reward){
        reward.textContent='✓ Semua misi selesai. Bonus +60 XP untuk simulasi ini sudah pernah diterima akunmu.';
      }
    }
  });
})();
